package br.com.sergio.gestaopedidos.entity;
import br.com.sergio.gestaopedidos.enums.TipoItemEstoque;import jakarta.persistence.*;import lombok.*;import org.hibernate.annotations.Check;import java.math.*;import java.time.LocalDateTime;
@Entity @Table(name="saldos_estoque",uniqueConstraints={@UniqueConstraint(name="uk_saldo_insumo",columnNames="insumo_id"),@UniqueConstraint(name="uk_saldo_produto",columnNames="produto_id")})
@Check(constraints="(insumo_id is not null and produto_id is null and tipo_item='INSUMO') or (insumo_id is null and produto_id is not null and tipo_item in ('PRODUTO_REVENDA','PRODUTO_PRODUZIDO'))")
@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder@EqualsAndHashCode(onlyExplicitlyIncluded=true)
public class SaldoEstoque{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@EqualsAndHashCode.Include private Long id;@Enumerated(EnumType.STRING)@Column(name="tipo_item",nullable=false,length=30,updatable=false)private TipoItemEstoque tipoItem;@OneToOne(fetch=FetchType.LAZY)@JoinColumn(name="insumo_id",unique=true)private Insumo insumo;@OneToOne(fetch=FetchType.LAZY)@JoinColumn(name="produto_id",unique=true)private Produto produto;@Column(name="quantidade_atual",nullable=false,precision=15,scale=3)@Builder.Default private BigDecimal quantidadeAtual=BigDecimal.ZERO.setScale(3);@Column(name="custo_medio_atual",nullable=false,precision=18,scale=6)@Builder.Default private BigDecimal custoMedioAtual=BigDecimal.ZERO.setScale(6);@Column(name="valor_total_estoque",nullable=false,precision=18,scale=2)@Builder.Default private BigDecimal valorTotalEstoque=BigDecimal.ZERO.setScale(2);@Column(name="atualizado_em",nullable=false)private LocalDateTime atualizadoEm;@Version private Long versao;@PrePersist@PreUpdate void atualizar(){atualizadoEm=LocalDateTime.now();}}
